WHERE CustomerCity = 'Tokyo';

SELECT OrderID, ProductName, FinalPrice
FROM Ecommerce
WHERE FinalPrice > 1000;

SELECT p.PresidentName, pm.SpouseName
FROM President p
LEFT JOIN PresidentMarriage pm ON p.PresidentName = pm.PresidentName;

SELECT pm.PresidentName, pm.SpouseName, p.PartyName
FROM PresidentMarriage pm
JOIN President p ON pm.PresidentName = p.PresidentName;

SELECT DISTINCT ph.PresidentName, ph.YearHolding, ph.RunnerUp
FROM PresidentHolding ph
JOIN President p ON p.PresidentName = ph.RunnerUp;

SELECT PartyName, COUNT(*) AS PresidentCount
FROM President
GROUP BY PartyName;

SELECT ph.PresidentName, MIN(ph.YearHolding) AS earliest_start_year, MAX(ph.YearEnd) AS latest_end_year
FROM PresidentHolding ph
GROUP BY ph.PresidentName;

SELECT MembershipTier, AVG(CustomerSatisfaction) AS AvgCustomerSatisfaction
FROM Ecommerce
GROUP BY MembershipTier;

SELECT DISTINCT ON (PaymentMethod) PaymentMethod, OrderID, Revenue
FROM Ecommerce
ORDER BY PaymentMethod, Revenue DESC;

SELECT PresidentName, (YearEnd - YearHolding) AS tenure
FROM PresidentHolding
WHERE (YearEnd - YearHolding) > (
  SELECT AVG(YearEnd - YearHolding)
  FROM PresidentHolding
);

